'use client';
import { Fragment, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { enter, Swap, useGrow } from '../lib/motion';
import { giveBack } from '../lib/popover';
import '../designme.css';
import './inline-text-diff.css';

export interface TextEdit {
  key: string;
  /** The words the copy has now, shown struck */
  from: string;
  /** The words the agent suggests instead */
  to: string;
  /** Why the agent isn't sure of this one. The edit is marked and the note shows above its buttons */
  note?: string;
}

/** A run of the copy as it stands, or one of the agent's edits to it */
export type TextPart = string | TextEdit;
export type EditDecision = 'accepted' | 'rejected';

export interface InlineTextDiffProps {
  /** What the copy is, like "Pricing intro" */
  title: string;
  /** The copy in order: plain strings, with the edits between them */
  parts: TextPart[];
  /** What was decided for each edit, by key. Leave an edit out while it waits */
  decisions?: Record<string, EditDecision>;
  defaultDecisions?: Record<string, EditDecision>;
  onDecisionsChange?: (decisions: Record<string, EditDecision>) => void;
  /** The line that replaces the buttons once every edit is decided, like "Saved to Pricing v4" */
  doneLabel?: string;
  labels?: { accept?: string; reject?: string; acceptAll?: string; rejectAll?: string };
  className?: string;
}

const isEdit = (p: TextPart): p is TextEdit => typeof p !== 'string';
/** The filled warning sign, as the warning notices draw it */
const WarnSign = () => <svg className="dm-itd-wi" viewBox="0 0 24 24" aria-hidden="true"><path className="dm-a" d="M12 3.6 2.6 19.9h18.8z" /><path className="dm-b" d="M12 9.6v4.4M12 17v.01" /></svg>;

/** The agent's edits to a piece of copy, struck and added inline. Each one opens a small toolbar to accept or reject it,
    and the header takes the rest all at once. */
export function InlineTextDiff({ title, parts, decisions, defaultDecisions = {}, onDecisionsChange, doneLabel = 'Every edit reviewed', labels = {}, className }: InlineTextDiffProps) {
  const [dec, setDec] = useControllable(decisions, defaultDecisions, onDecisionsChange);
  const [cur, setCur] = useState<string | null>(null);
  const [at, setAt] = useState({ left: 0, top: 0, up: false });
  // no room is kept for the end: the card eases shorter as edits fold into the text, and grows for the note at the end
  const [root, inner] = useGrow();
  const bar = useRef<HTMLDivElement>(null);
  const chunks = useRef(new Map<string, HTMLSpanElement>());
  const L = { accept: 'Accept', reject: 'Reject', acceptAll: 'Accept all', rejectAll: 'Reject all', ...labels };
  const edits = parts.filter(isEdit);
  const left = edits.filter(e => !dec[e.key]).length, yes = edits.filter(e => dec[e.key] === 'accepted').length;
  const status = left === edits.length ? `${left} edits to review` : left ? `${left} of ${edits.length} left` : `${yes} accepted, ${edits.length - yes} rejected`;
  const open = edits.find(e => e.key === cur);
  // the toolbar keeps the last edit's note while it fades out
  const last = useRef<TextEdit | undefined>(undefined); if (open) last.current = open;
  // the toolbar opens under the edit's last line, or over its first when the page (or a box that clips it) has no room
  // below; inside a scaled preview the offsets are divided by its scale
  useLayoutEffect(() => {
    const r = root.current, b = bar.current, el = cur ? chunks.current.get(cur) : null; if (!r || !b || !el) return;
    const rb = r.getBoundingClientRect(), k = rb.width / r.offsetWidth || 1, rs = el.getClientRects(), cr = rs[rs.length - 1] ?? el.getBoundingClientRect(), c0 = rs[0] ?? cr;
    let top = 0, bottom = innerHeight;
    for (let a = r.parentElement; a && a !== document.documentElement; a = a.parentElement) {
      if (getComputedStyle(a).overflowY === 'visible') continue;
      const ar = a.getBoundingClientRect(); top = Math.max(top, ar.top); bottom = Math.min(bottom, ar.bottom);
    }
    const h = b.offsetHeight * k, up = cr.bottom + 6 + h > bottom - 8 && c0.top - 6 - h >= top + 8;
    setAt({ left: Math.max(12, Math.min(((up ? c0 : cr).left - rb.left) / k, r.offsetWidth - b.offsetWidth - 12)), top: up ? (c0.top - rb.top) / k - 6 - b.offsetHeight : (cr.bottom - rb.top) / k + 6, up });
  }, [cur]);
  // Enter or Space opens an edit's toolbar with the focus on Accept, as a dialog takes the focus; Escape brings it back
  const keyOpen = useRef(false);
  useLayoutEffect(() => { if (cur && keyOpen.current) { keyOpen.current = false; bar.current?.querySelector<HTMLElement>('.dm-itd-acc')?.focus({ preventScroll: true }); } }, [cur]);
  // a click anywhere else closes it
  useEffect(() => {
    if (!cur) return;
    const down = (e: PointerEvent) => { const t = e.target as Element; if (!bar.current?.contains(t) && !t.closest?.('.dm-itd-c')) setCur(null); };
    document.addEventListener('pointerdown', down);
    return () => document.removeEventListener('pointerdown', down);
  }, [cur]);

  const decide = (s: EditDecision) => {
    if (!cur) return;
    const back = bar.current?.contains(document.activeElement), el = chunks.current.get(cur);
    setDec({ ...dec, [cur]: s }); setCur(null);
    // the focus goes back to the edit, with a ring only when the answer came from the keyboard (a click never leaves one)
    if (back && el) giveBack(el);
  };
  const all = (s: EditDecision) => { setCur(null); setDec({ ...Object.fromEntries(edits.filter(e => !dec[e.key]).map(e => [e.key, s])), ...dec }); };

  return (
    <div data-dm="" className={className} style={{ width: '100%' }}
      onKeyDown={e => { if (e.key === 'Escape' && cur) { const el = chunks.current.get(cur); setCur(null); el?.focus({ preventScroll: true }); } }}>
      <div ref={root} className="dm-itd dm-panel dm-growing">
        <div ref={inner} className="dm-grow">
        <div className="dm-itd-h">
          <div className="dm-itd-ht"><b>{title}</b><Swap className="dm-muted dm-itd-st">{status}</Swap></div>
          {left > 0 && (
            <div className="dm-itd-a">
              <button type="button" className="dm-pill dm-ghost dm-sm dm-itd-no" onClick={() => all('rejected')}>{L.rejectAll}</button>
              <button type="button" className="dm-pill dm-primary dm-sm dm-itd-ok" onClick={() => all('accepted')}>{L.acceptAll}</button>
            </div>
          )}
        </div>
        <p className="dm-itd-t">
          {parts.map((p, i) => {
            if (!isEdit(p)) return <Fragment key={i}>{p}</Fragment>;
            const n = edits.indexOf(p), d = dec[p.key];
            return (
              <span key={p.key} ref={el => { if (el) chunks.current.set(p.key, el); else chunks.current.delete(p.key); }} data-edit={p.key}
                className={cx('dm-itd-c', p.note && 'dm-unsure', cur === p.key && 'dm-on', d === 'accepted' && 'dm-acc', d === 'rejected' && 'dm-rej')}
                role="button" tabIndex={0} aria-haspopup="dialog" aria-expanded={cur === p.key} aria-label={`Edit ${n + 1} of ${edits.length}: ${p.from}, suggested ${p.to}`}
                onClick={() => setCur(cur === p.key ? null : p.key)}
                onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); keyOpen.current = cur !== p.key; setCur(cur === p.key ? null : p.key); } }}>
                <del>{p.from}</del><ins>{p.to}</ins>
              </span>
            );
          })}
        </p>
        {/* the end: a neutral line with the green tick, only once every edit is decided. It comes in a beat after the card
            starts to grow for it, so it never shows past the card's edge */}
        <p className="dm-itd-f" aria-live="polite">
          {left === 0 && <span className="dm-enter" style={{ ...enter(220).style, display: 'inline-flex', alignItems: 'center', gap: 6 }}><Icon name="ok" size="xs" /><span>{doneLabel}</span></span>}
        </p>
        </div>
        {/* an edit the agent isn't sure of: the toolbar is a warning notice, and Reject, which settles it, is the warning's button */}
        <div ref={bar} className={cx('dm-itd-bar', open && 'dm-open', at.up && 'dm-up', last.current?.note && 'dm-unsure')} role="dialog" aria-label="Edit" inert={!open} style={{ left: at.left, top: at.top }}
          // the left and right arrows move between Accept and Reject
          onKeyDown={e => { const bs = Array.from(bar.current?.querySelectorAll<HTMLElement>('button') ?? []), j = bs.indexOf(document.activeElement as HTMLElement); if (j < 0) return;
            const d = ({ ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 } as Record<string, number>)[e.key], to = d ? bs[(j + d + bs.length) % bs.length] : e.key === 'Home' ? bs[0] : e.key === 'End' ? bs[bs.length - 1] : null;
            if (to) { e.preventDefault(); to.focus({ preventScroll: true }); } }}>
          {last.current?.note && <p className="dm-itd-why"><WarnSign /><span>{last.current.note}</span></p>}
          <div className="dm-itd-bb">
            <button type="button" className={cx('dm-pill dm-sm dm-itd-acc', last.current?.note ? 'dm-ghost' : 'dm-primary')} onClick={() => decide('accepted')}><Icon name="check" size="xs" />{L.accept}</button>
            <button type="button" className={cx('dm-pill dm-sm dm-itd-rej', last.current?.note ? 'dm-warn' : 'dm-ghost')} onClick={() => decide('rejected')}><Icon name="x" size="xs" />{L.reject}</button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Inline text diff ---------- */
/* a piece of copy with the agent's edits marked inline, struck and added; each edit opens a small toolbar to accept or
   reject it, and an edit the agent isn't sure of says why */
.dm-itd{position:relative;width:100%;max-width:440px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-itd-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.dm-itd-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-itd-ht b{font-weight:500;font-size:14px}
.dm-itd-st{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-itd-a{display:flex;gap:6px;flex:none}
/* a narrow card (a phone) gives the title and the count their whole line, and the two buttons a row of their own under
   them, ending on the content's right edge, so the count is never cut short */
.dm-itd{container-type:inline-size}
@container (max-width:300px){.dm-itd-h{flex-wrap:wrap;row-gap:var(--dm-s-3)}.dm-itd-ht{flex:1 1 100%}.dm-itd-a{margin-left:auto}}
.dm-itd-t{margin:0;font-size:14px;line-height:1.8;color:var(--dm-fg)}
/* an edit's words start where the line starts (the text's own column), so their tints reach out round them with a shadow
   rather than pushing them in with padding */
.dm-itd-c{padding:2px 0;border-radius:var(--dm-r-tiny,5px);cursor:pointer;outline:0;transition:background .16s;-webkit-box-decoration-break:clone;box-decoration-break:clone}
.dm-itd-c.dm-on{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-itd-c:hover{background:var(--dm-row)}}
.dm-itd-c:focus-visible{box-shadow:0 0 0 2px var(--dm-focus)}
/* removed words in the red text colour on its tint, struck with the bright red mark; added words in the green text colour on
   its tint (each 4.5:1 on its tint); an addition the agent isn't sure of in the warning's text colour on its tint */
/* (each tint is laid over the surface, so the quiet fill under an open edit never shows through it and lowers its contrast;
   the 2px of padding round the words is taken back by a margin, so the words keep their place on the line) */
.dm-itd-c del{color:var(--dm-bad);text-decoration:line-through;text-decoration-color:var(--dm-bad-mark);text-decoration-thickness:1px;background:linear-gradient(var(--dm-bad-bg),var(--dm-bad-bg)),var(--dm-surface);border-radius:var(--dm-r-tiny,3px);padding:0 2px;margin:0 6px 0 -2px}
.dm-itd-c ins{color:var(--dm-ok);text-decoration:none;background:linear-gradient(var(--dm-ok-bg),var(--dm-ok-bg)),var(--dm-surface);border-radius:var(--dm-r-tiny,3px);padding:0 2px;margin-left:-2px}
.dm-itd-c.dm-unsure ins{color:var(--dm-warn);background:linear-gradient(var(--dm-warn-bg),var(--dm-warn-bg)),var(--dm-surface)}
.dm-itd-c.dm-acc del,.dm-itd-c.dm-rej ins{display:none}
.dm-itd-c.dm-acc ins,.dm-itd-c.dm-rej del{color:inherit;background:none;text-decoration:none;margin:0;padding:0}
/* no room is kept for the end (owner, 18 Nov): the card eases shorter as edits fold into the text and grows for the note at
   the end (grow()); the toolbar opens out of it, so nothing clips it */
.dm-itd.dm-growing{overflow:visible}
/* an edit's toolbar opens under its last line, or over its first when the stage has no room below */
.dm-itd-bar{position:absolute;left:0;top:0;z-index:5;display:flex;flex-direction:column;gap:var(--dm-s-2);padding:var(--dm-s-2);width:max-content;max-width:260px;border-radius:var(--dm-r-in);background:var(--dm-raised);box-shadow:var(--dm-shadow-pop);opacity:0;transform:translateY(-4px);visibility:hidden;pointer-events:none;transition:opacity .16s,transform .32s var(--dm-ease),visibility 0s .32s}
.dm-itd-bar.dm-up{transform:translateY(4px)}
.dm-itd-bar.dm-open{opacity:1;transform:none;visibility:visible;pointer-events:auto;transition-delay:0s}
/* an edit the agent isn't sure of: its toolbar is a warning notice (owner, 18 Nov): a faint warning tint, the filled warning
   sign in the bright orange, the words in the text colour, and the answer that settles it, Reject, as .pill.warn, with Accept
   the white button beside it */
.dm-itd-bar.dm-unsure{background:linear-gradient(color-mix(in srgb,var(--dm-warn-bg) 45%,transparent),color-mix(in srgb,var(--dm-warn-bg) 45%,transparent)),var(--dm-surface)}
.dm-itd-why{margin:0;display:flex;gap:var(--dm-s-2);padding:2px 2px 0;font-size:12.5px;line-height:18px;color:var(--dm-fg)}
.dm-itd-wi{width:16px;height:16px;flex:none;margin-top:1px;overflow:visible}
/* (a step of --dm-warn in the bright orange keeps the sign at 3:1 on the notice's tint, as Attachment tray's strip tick does) */
.dm-itd-wi .dm-a{fill:color-mix(in srgb,var(--dm-warn-mark) 85%,var(--dm-warn));stroke:color-mix(in srgb,var(--dm-warn-mark) 85%,var(--dm-warn));stroke-width:2;stroke-linejoin:round}
.dm-itd-wi .dm-b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.dm-itd-bb{display:flex;gap:6px}
.dm-itd-bar.dm-unsure .dm-itd-bb{justify-content:flex-end}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.dm-itd .dm-pill:active{transform:none}
.dm-itd-bar.dm-unsure .dm-itd-acc{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.dm-itd-bar.dm-unsure .dm-itd-acc:hover{background:var(--dm-surface);box-shadow:var(--dm-on-tint-btn-h)}}
/* the end: a neutral line with the green tick (owner, 18 Nov), only once every edit is decided */
/* the line saying how the review went sits under a hairline in Soft and Blueprint (owner, 21 Nov), 12px from it on each side */
.dm-itd-f{margin:0;display:flex;align-items:center;gap:6px;padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px;line-height:20px;color:var(--dm-fg)}
.dm-itd-f:empty{display:none}
/* Clean: the line saying how the review went is the card's off-white foot strip (owner, 21 Nov), its words 16px in */
:root[data-style="clean"] .dm-itd-f,:root [data-style="clean"] .dm-itd-f,:root [data-style="clean"].dm-itd-f{padding-top:0;border-top:0}
:root[data-style="clean"] .dm-itd.dm-panel .dm-itd-f,:root [data-style="clean"] .dm-itd.dm-panel .dm-itd-f,:root [data-style="clean"].dm-itd.dm-panel .dm-itd-f{margin:var(--dm-s-1) -16px -16px;padding:calc(var(--dm-strip-y) + 5px) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card);line-height:18px}
/* empty, it takes no room (the gap above it is taken back) but stays in place, so the end is read out when it comes */
.dm-itd-f:empty{min-height:0;margin-top:calc(-1 * var(--dm-s-3))}
.dm-itd-f svg{flex:none;color:var(--dm-ok-mark)}
/* Clean (owner, 19 Nov): its content 16px from every edge; the toolbar is a round popover, its corners concentric with its
   28px buttons 8px in (22px), scaling and fading from the edit; on an unsure edit Accept is Clean's flat white button */
:root[data-style="clean"] .dm-itd.dm-panel,:root [data-style="clean"] .dm-itd.dm-panel,:root [data-style="clean"].dm-itd.dm-panel{padding:16px}
/* the head sits over a hairline that runs edge to edge, 16px under it, and the text starts 16px under the hairline (owner,
   22 Nov: a divider at the top for Clean, so its parts read as segments, as the foot strip does at the bottom) */
:root[data-style="clean"] .dm-itd.dm-panel .dm-itd-h,:root [data-style="clean"] .dm-itd.dm-panel .dm-itd-h,:root [data-style="clean"].dm-itd.dm-panel .dm-itd-h{margin-inline:-16px;padding:0 16px 16px;border-bottom:1px solid var(--dm-line)}
:root[data-style="clean"] .dm-itd-ht b,:root [data-style="clean"] .dm-itd-ht b,:root [data-style="clean"].dm-itd-ht b{line-height:20px}
:root[data-style="clean"] .dm-itd-st,:root [data-style="clean"] .dm-itd-st,:root [data-style="clean"].dm-itd-st{line-height:18px}
:root[data-style="clean"] .dm-itd-c,:root [data-style="clean"] .dm-itd-c,:root [data-style="clean"].dm-itd-c{transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-itd-bar,:root [data-style="clean"] .dm-itd-bar,:root [data-style="clean"].dm-itd-bar{border-radius:var(--dm-r-card);transform:translateY(-4px) scale(.96);transform-origin:top left;transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease),visibility 0s var(--dm-t)}
:root[data-style="clean"] .dm-itd-bar.dm-up,:root [data-style="clean"] .dm-itd-bar.dm-up,:root [data-style="clean"].dm-itd-bar.dm-up{transform:translateY(4px) scale(.96);transform-origin:bottom left}
:root[data-style="clean"] .dm-itd-bar.dm-open,:root [data-style="clean"] .dm-itd-bar.dm-open,:root [data-style="clean"].dm-itd-bar.dm-open{transform:none;transition-delay:0s}
:root[data-style="clean"] .dm-itd-bar.dm-unsure .dm-itd-acc,:root [data-style="clean"] .dm-itd-bar.dm-unsure .dm-itd-acc,:root [data-style="clean"].dm-itd-bar.dm-unsure .dm-itd-acc{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-itd-bar.dm-unsure .dm-itd-acc:hover,:root [data-style="clean"] .dm-itd-bar.dm-unsure .dm-itd-acc:hover,:root [data-style="clean"].dm-itd-bar.dm-unsure .dm-itd-acc:hover{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-itd-bar.dm-unsure .dm-itd-acc:hover,:root [data-style="clean"] .dm-itd-bar.dm-unsure .dm-itd-acc:hover,:root [data-style="clean"].dm-itd-bar.dm-unsure .dm-itd-acc:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .dm-itd-bar.dm-unsure .dm-itd-acc:active,:root [data-style="clean"] .dm-itd-bar.dm-unsure .dm-itd-acc:active,:root [data-style="clean"].dm-itd-bar.dm-unsure .dm-itd-acc:active{box-shadow:var(--dm-btn2-press)}
